22	@Repository
23	public class ClaimRepository {
24	
25	    private static final String COLUMNS = "id, person_id, amount, claim_date, note, status, claim_no, settled_due, opened_by, stated, stated_due, corrects, due_by, stated_na, deferred_until, proofs, split_from, late_entry, reminded, ref, tags, void_reason, waived, proofs_photo, held,"
26	            + " (status = 'OPEN' AND deferred_until IS NOT NULL AND deferred_until > (SELECT s.today FROM sheet s WHERE s.id = claim.sheet_id)) AS deferred";
27	
28	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person_id"),
29	            money(rs.getBigDecimal("amount")), rs.getDate("claim_date").toLocalDate().toString(),
30	            rs.getString("note"), rs.getString("status"),
31	            rs.getString("claim_no"), dueOf(rs.getBigDecimal("settled_due")),
32	            rs.getString("opened_by"), rs.getBoolean("stated"), dueOf(rs.getBigDecimal("stated_due")),
33	            rs.getString("corrects"), rs.getDate("due_by").toLocalDate().toString(),
34	            rs.getBoolean("stated_na"),
35	            rs.getDate("deferred_until") == null ? null : rs.getDate("deferred_until").toLocalDate().toString(),
36	            rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"),
37	            rs.getBoolean("late_entry"),
38	            rs.getDate("reminded") == null ? null : rs.getDate("reminded").toLocalDate().toString(),
39	            rs.getString("ref"), rs.getString("tags"), rs.getString("void_reason"), rs.getBoolean("waived"), rs.getInt("proofs_photo"), rs.getBoolean("held"));
40	
41	    /** The grade a person (sheet, person id) has on a date: the one with the latest from-date on
42	     *  or before it, the first one they were given applying from the beginning of time. */
43	    private static final String GRADE_ON = "(SELECT g.grade FROM person_grade g WHERE g.sheet_id = ? AND g.person_id = ?"
44	            + " AND (g.from_date IS NULL OR g.from_date <= CAST(? AS DATE)) ORDER BY g.from_date DESC NULLS LAST LIMIT 1)";
45	
46	    /** The rate a sheet has for a grade on a date (sheet, grade, then the date): the one with the latest
47	     *  from-date on or before it, an undated rate applying from the beginning of time; at most one row, with
48	     *  its pct and to_date. */
49	    private static final String RATE_FOR = "(SELECT r.pct, r.to_date FROM rate r WHERE r.sheet_id = ? AND r.grade = ?"
50	            + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE)) ORDER BY r.from_date DESC NULLS LAST LIMIT 1)";
51	
52	    /** The rate a sheet's claim takes for a grade on a date (sheet, grade, the date, then the claim's added number):
53	     *  as {@link #RATE_FOR}, among only the rate versions that apply to the claim — those that apply to every claim
54	     *  and the forward-only ones saved before it was added — the newest version of each from-date; at most one row,
55	     *  with its pct and to_date. */
56	    private static final String CLAIM_RATE_FOR = "(SELECT r.pct, r.to_date FROM (SELECT sheet_id, grade, from_date, version,"
57	            + " pct, to_date, after_seq FROM rate UNION ALL SELECT sheet_id, grade, from_date, version, pct, to_date, after_seq"
58	            + " FROM rate_version) r WHERE r.sheet_id = ? AND r.grade = ?"
59	            + " AND (r.from_date IS NULL OR r.from_date <= CAST(? AS DATE)) AND (r.after_seq IS NULL OR r.after_seq < ?)"
60	            + " ORDER BY r.from_date DESC NULLS LAST, r.version DESC LIMIT 1)";
61	
62	    private final JdbcTemplate jdbc;
63	    private final SettingsRepository settings;
64	    private final HistoryRepository history;
65	
66	    public ClaimRepository(JdbcTemplate jdbc, SettingsRepository settings, HistoryRepository history) {
67	        this.jdbc = jdbc;
68	        this.settings = settings;
69	        this.history = history;
70	    }
71	
72	    /** Keep a claim's values in the sheet's history after a change to it; whether it changed. */
73	    private boolean kept(String sheetId, long claimId, boolean changed) {
74	        if (changed) history.claim(sheetId, claimId);
75	        return changed;
76	    }
77	
78	    public boolean personExists(String sheetId, long personId) {
79	        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND id = ?",
80	                Integer.class, sheetId, personId);
81	        return known != null && known > 0;
82	    }
83	
84	    /** The given claims as the sheet lists them: people in list order (by their position), each person's claims
85	     *  newest first (a reassigned claim counts as its new person's newest); ids the sheet does not have are left out. */
86	    public List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
87	        List<Claim> out = new ArrayList<>();
88	        for (Claim c : list(sheetId)) {
89	            if (ids.contains(c.id())) out.add(c);
90	        }
91	        Map<Long, Integer> place = new java.util.HashMap<>();
92	        for (Long pid : jdbc.queryForList("SELECT id FROM person WHERE sheet_id = ? ORDER BY list_position, id",
93	                Long.class, sheetId)) {
94	            place.put(pid, place.size());
95	        }
96	        out.sort(Comparator.comparingInt((Claim c) -> place.getOrDefault(c.personId(), Integer.MAX_VALUE)));
97	        return out;
98	    }
99	
100	    /** The sheet's claims, newest first. */
101	    public List<Claim> list(String sheetId) {
102	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY listed DESC, id DESC", ROW, sheetId);
103	    }
104	
105	    /** A claim on the sheet; null when the sheet has no such claim. */
106	    public Claim find(String sheetId, long claimId) {
107	        List<Claim> found = jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW,
108	                sheetId, claimId);
109	        return found.isEmpty() ? null : found.get(0);
110	    }
111	
112	    /** Move a claim to a status, only when it is now in one of {@code from}; false when it is not. */
113	    public boolean changeStatus(String sheetId, long claimId, List<String> from, String to) {
114	        String in = String.join(", ", from.stream().map(s -> "?").toList());
115	        List<Object> args = new ArrayList<>(List.of(to, claimId, sheetId));
116	        args.addAll(from);
117	        return kept(sheetId, claimId, jdbc.update("UPDATE claim SET status = ? WHERE id = ? AND sheet_id = ? AND status IN (" + in + ")",
118	                args.toArray()) > 0);
119	    }
120	
121	    /** Record the sheet's today as the claim's review day (it has just gone to REVIEW). */
122	    public void reviewDay(String sheetId, long claimId) {
123	        kept(sheetId, claimId, jdbc.update("UPDATE claim SET review_day = ? WHERE id = ? AND sheet_id = ?",
124	                java.sql.Date.valueOf(settings.today(sheetId)), claimId, sheetId) > 0);
125	    }
126	
127	    /** Whether each REVIEW claim of the sheet is review-late (its review day plus the sheet's review SLA is before the
128	     *  sheet's today; none is while the SLA is blank), by claim id. */
129	    public Map<String, Boolean> reviewLate(String sheetId) {
130	        Map<String, Boolean> late = new LinkedHashMap<>();
131	        Integer sla = settings.reviewSla(sheetId);
132	        if (sla == null) return late;
133	        LocalDate today = settings.today(sheetId);
134	        jdbc.query("SELECT id, review_day FROM claim WHERE sheet_id = ? AND status = 'REVIEW' AND review_day IS NOT NULL",
135	                rs -> {
136	                    late.put(String.valueOf(rs.getLong("id")),
137	                            rs.getDate("review_day").toLocalDate().plusDays(sla).isBefore(today));
138	                }, sheetId);
139	        return late;
140	    }
141	
142	    /** Record the reason a claim was voided with. */
143	    public void voidReason(String sheetId, long claimId, String reason) {
144	        kept(sheetId, claimId, jdbc.update("UPDATE claim SET void_reason = ? WHERE id = ? AND sheet_id = ?", reason, claimId, sheetId) > 0);
145	    }
146	
147	    /** Give an opened claim the next number of its sheet's tree within the fiscal year its due-by ({@code date})
148	     *  falls in, FY<yyyy>-<n>: one after the last number given in that fiscal year on any sheet of the tree (the
149	     *  sheet's topmost ancestor and all its descendants). The fiscal year follows the sheet's fiscal start month.
150	     *  The tree's sheet rows stay locked until the transaction commits, so two claims opened at once anywhere in
151	     *  the tree get consecutive numbers. */
152	    public String number(String sheetId, long claimId, LocalDate date) {
153	        List<String> tree = tree(sheetId);
154	        String in = String.join(",", java.util.Collections.nCopies(tree.size(), "?"));
155	        jdbc.update("UPDATE sheet SET claim_number = claim_number WHERE id IN (" + in + ")", tree.toArray());
156	        Integer startMonth = jdbc.queryForObject("SELECT fiscal_start_month FROM sheet WHERE id = ?", Integer.class, sheetId);
157	        int year = date.getMonthValue() >= (startMonth == null ? 1 : startMonth) ? date.getYear() : date.getYear() - 1;
158	        String key = "FY" + year;
159	        List<Object> args = new ArrayList<>(tree);
160	        args.add(key);
161	        Long last = jdbc.queryForObject("SELECT MAX(last_no) FROM claim_sequence WHERE sheet_id IN (" + in + ")"
162	                + " AND seq_key = ?", Long.class, args.toArray());
163	        long next = (last == null ? 0 : last) + 1;
164	        if (jdbc.update("UPDATE claim_sequence SET last_no = ? WHERE sheet_id = ? AND seq_key = ?", next, sheetId, key) == 0) {
165	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, ?)", sheetId, key, next);
166	        }
167	        String number = key + "-" + next;
168	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
169	        kept(sheetId, claimId, true);
170	        return number;
171	    }
172	
173	    /** The sheets of the sheet's tree, sorted: its topmost ancestor (following parents) and all that one's
174	     *  descendants, the sheet itself always among them. */
175	    private List<String> tree(String sheetId) {
176	        String root = sheetId;
177	        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
178	        for (String at = parentOf(root); at != null && seen.add(at); at = parentOf(at)) root = at;
179	        java.util.Set<String> found = new java.util.TreeSet<>(List.of(root));
180	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(root));
181	        while (!pending.isEmpty()) {
182	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent_id = ?", String.class, pending.poll())) {
183	                if (found.add(child)) pending.add(child);
184	            }
185	        }
186	        found.add(sheetId);
187	        return new ArrayList<>(found);
188	    }
189	
190	    private String parentOf(String sheetId) {
191	        List<String> found = jdbc.queryForList("SELECT parent_id FROM sheet WHERE id = ?", String.class, sheetId);
192	        return found.isEmpty() ? null : found.get(0);
193	    }
194	
195	    /** Whether claims opened now are numbered per period: the sheet's period numbering from-date is set
196	     *  and its today is on or after it. */
197	    public boolean numbersPerPeriod(String sheetId) {
198	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ? AND period_numbering_from IS NOT NULL"
199	                + " AND today >= period_numbering_from", Integer.class, sheetId);
200	        return n != null && n > 0;
201	    }
202	
203	    /** Give an opened claim the next number in the sequence of the period its due-by ({@code date}) falls in,
204	     *  <period name>-<n>, or X-<n> when it is in no period. The sheet's row is locked first, so two
205	     *  claims opened at once get consecutive numbers. */
206	    public String numberInPeriod(String sheetId, long claimId, LocalDate date) {
207	        jdbc.update("UPDATE sheet SET claim_number = claim_number WHERE id = ?", sheetId);
208	        List<Object[]> period = periodOn(sheetId, date);
209	        String key = period.isEmpty() ? "X" : "P" + period.get(0)[0];
210	        String prefix = period.isEmpty() ? "X" : (String) period.get(0)[1];
211	        if (jdbc.update("UPDATE claim_sequence SET last_no = last_no + 1 WHERE sheet_id = ? AND seq_key = ?",
212	                sheetId, key) == 0) {
213	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, 1)", sheetId, key);
214	        }
215	        Long next = jdbc.queryForObject("SELECT last_no FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?",
216	                Long.class, sheetId, key);
217	        String number = prefix + "-" + next;
218	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
219	        kept(sheetId, claimId, true);
220	        return number;
221	    }
222	
223	    /** The period a date falls in, as [id, name] (the earliest by from-date), or none. */
224	    private List<Object[]> periodOn(String sheetId, LocalDate date) {
225	        return jdbc.query("SELECT id, name FROM period WHERE sheet_id = ? AND from_date <= ?"
226	                + " AND to_date >= ? ORDER BY from_date LIMIT 1",
227	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getString("name") }, sheetId, Date.valueOf(date),
228	                Date.valueOf(date));
229	    }
230	
231	    /** Re-date an OPEN or PENDING claim (its due-by and statement binding stay as they are); false when the
232	     *  sheet has no such claim in those statuses. */
233	    public boolean redate(String sheetId, long claimId, LocalDate date) {
234	        return kept(sheetId, claimId, jdbc.update("UPDATE claim SET claim_date = ? WHERE id = ? AND sheet_id = ? AND status IN ('OPEN', 'PENDING')",
235	                Date.valueOf(date), claimId, sheetId) > 0);
236	    }
