238	    /** Record who last edited a claim. */
239	    public void editedBy(String sheetId, long claimId, String by) {
240	        jdbc.update("UPDATE claim SET edited_by = ? WHERE id = ? AND sheet_id = ?", by, claimId, sheetId);
241	    }
242	
243	    /** Who last edited a claim; null when it was never edited. */
244	    public String editedBy(String sheetId, long claimId) {
245	        List<String> by = jdbc.queryForList("SELECT edited_by FROM claim WHERE id = ? AND sheet_id = ?", String.class, claimId, sheetId);
246	        return by.isEmpty() ? null : by.get(0);
247	    }
248	
249	    /** Record who opened a claim. */
250	    public void openedBy(String sheetId, long claimId, String by) {
251	        jdbc.update("UPDATE claim SET opened_by = ? WHERE id = ? AND sheet_id = ?", by, claimId, sheetId);
252	    }
253	
254	    /** A claim's due now: its amount at the rate, in force on the claim's date, for the grade its person
255	     *  had on that date, falling back to the parent sheets' (see {@link #rateInForce})
256	     *  (the one with the latest from-date on or before it; an undated rate applies from the beginning
257	     *  of time; none applies when the claim's date is after that rate's to-date), rounded to two decimals by the claim's
258	     *  rounding (see {@link #rounding}) — the rate figure, not floored: the floor is applied before the late charge, in {@link #dueNow};
259	     *  null when no rate applies. */
260	    public BigDecimal due(String sheetId, Claim claim) {
261	        BigDecimal pct = rateInForce(sheetId, claim.personId(), LocalDate.parse(claim.date()), added(sheetId, claim.id()));
262	        if (pct == null) return null;
263	        BigDecimal due = new BigDecimal(claim.amount()).multiply(pct).movePointLeft(2)
264	                .setScale(2, rounding(sheetId, claim));
265	        return due;
266	    }
267	
268	    /** How a claim's live figures round: by the sheet's rounding mode in force on the claim's date (half-up or
269	     *  half-even) when there is one; else half up when the claim is dated before the sheet's policy date
270	     *  (blank meaning the sheet's today), else half to even. A correction rounds by the date of the
271	     *  claim it corrects (its person's claim with that number), not its own. */
272	    public RoundingMode rounding(String sheetId, Claim claim) {
273	        String date = claim.date();
274	        if (claim.corrects() != null) {
275	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
276	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
277	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
278	        }
279	        List<String> mode = jdbc.queryForList("SELECT setting FROM setting_value WHERE sheet_id = ? AND setting_key = 'rounding'"
280	                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1", String.class, sheetId, Date.valueOf(LocalDate.parse(date)));
281	        RoundingMode set = mode.isEmpty() ? null : SettingsRepository.roundingMode(mode.get(0));
282	        if (set != null) return set;
283	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
284	                Date.class, sheetId);
285	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
286	        return LocalDate.parse(date).isBefore(policy.get(0).toLocalDate()) ? RoundingMode.HALF_UP
287	                : RoundingMode.HALF_EVEN;
288	    }
289	
290	    /** A claim's figure now: the due fixed when it was settled, else the due as shown its last statement bound
291	     *  it to (floor and late charge included; none when it bound it to n/a), else its live rate figure (not floored);
292	     *  null when it has none. */
293	    public BigDecimal figure(String sheetId, Claim claim) {
294	        if (claim.due() != null) return new BigDecimal(claim.due());
295	        if (claim.bound() && claim.statedNa()) return null;
296	        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
297	        return due(sheetId, claim);
298	    }
299	
300	    /** A claim's due now: a settled claim's frozen due; else its floored figure (the greater of the sheet's floor in
301	     *  force on the claim's date and its live rate figure) plus, while it
302	     *  is overdue (OPEN or PENDING and its due-by — fixed when it was created — plus its grade's grace days before the
303	     *  sheet's today), for every full 30 days it is overdue, the sheet's late percent in force on that boundary date (the
304	     *  due-by plus the grace plus 30, 60,
305	     *  90 ... days) of that figure plus the charges of the boundaries before it (compounding), each rounded to two decimals by the claim's rounding, the charges added up (a
306	     *  boundary whose percent is 0.00 adds nothing). A claim bound by a statement shows the due its last statement
307	     *  bound it to, as it was shown then (late charge and floor included): its charge no longer follows the sheet's
308	     *  today until the statement is cancelled. A correction (a negative amount) has no floor and no late charge,
309	     *  nor does a deferred claim have a charge (it is not overdue). Null when it has no figure. */
310	    public BigDecimal dueNow(String sheetId, Claim claim) {
311	        if (claim.due() != null) return new BigDecimal(claim.due());
312	        if (claim.bound() && (claim.statedNa() || claim.statedDue() != null)) return figure(sheetId, claim);
313	        BigDecimal figure = figure(sheetId, claim);
314	        if (figure == null || new BigDecimal(claim.amount()).signum() < 0) return figure;
315	        BigDecimal floored = figure.max(settings.floor(sheetId, LocalDate.parse(claim.date())));
316	        return floored.add(lateCharge(sheetId, claim, floored));
317	    }
318	
319	    /** The day a claim's overdue days are counted from: its due-by plus the grace days, in force on the claim's date,
320	     *  of the grade its person had on that date (its due-by when that grade has no grace then). The claim is overdue
321	     *  while open, not deferred, and this day is before the sheet's today; its 30-day late charge boundaries count
322	     *  from it. */
323	    public LocalDate overdueFrom(String sheetId, Claim claim) {
324	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
325	        String grade = gradeOn(sheetId, claim);
326	        if (grade == null) return dueBy;
327	        Integer grace = settings.gradeGrace(sheetId, grade, LocalDate.parse(claim.date()));
328	        return grace == null ? dueBy : dueBy.plusDays(grace);
329	    }
330	
331	    /** The grade a claim's person had on the claim's date; null when none. */
332	    public String gradeOn(String sheetId, Claim claim) {
333	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId,
334	                claim.personId(), claim.date());
335	        return grade.isEmpty() ? null : grade.get(0);
336	    }
337	
338	    /** The grade a person had on a day; null when none. */
339	    public String gradeOn(String sheetId, long personId, LocalDate day) {
340	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId,
341	                personId, day.toString());
342	        return grade.isEmpty() ? null : grade.get(0);
343	    }
344	
345	    /** Whether a claim is overdue on a day: open, not deferred, and its overdue-from day (see {@link #overdueFrom})
346	     *  before that day. */
347	    public boolean overdue(String sheetId, Claim claim, LocalDate today) {
348	        return claim.open() && !claim.deferred() && overdueFrom(sheetId, claim).isBefore(today);
349	    }
350	
351	    /** The late charge on a claim's figure now (see {@link #dueNow}); zero when it is not overdue. */
352	    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure) {
353	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
354	        if (!claim.open() || claim.deferred() || claim.waived()) return charge;
355	        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
356	        if (found.isEmpty()) return charge;
357	        LocalDate today = found.get(0).toLocalDate();
358	        LocalDate dueBy = overdueFrom(sheetId, claim);
359	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
360	        if (periods == 0) return charge;
361	        RoundingMode rounding = rounding(sheetId, claim);
362	        for (long n = 1; n <= periods; n++) {
363	            BigDecimal pct = settings.latePct(sheetId, dueBy.plusDays(30 * n));
364	            if (pct == null || pct.signum() == 0) continue;
365	            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
366	        }
367	        return charge;
368	    }
369	
370	    /** Whether the rate that would apply to a claim (for the grade its person had on its date, the one
371	     *  with the latest from-date on or before it) has ended before the claim's date. */
372	    public boolean rateEnded(String sheetId, Claim claim) {
373	        String grade = gradeOn(sheetId, claim);
374	        if (grade == null) return false;
375	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM " + CLAIM_RATE_FOR + " a"
376	                + " WHERE a.to_date < CAST(? AS DATE)", Integer.class, sheetId, grade, claim.date(),
377	                added(sheetId, claim.id()), claim.date());
378	        return n != null && n > 0;
379	    }
380	
381	    /** A claim's added number (see V83__forward_only_rate.sql): claims added later have higher ones; the highest
382	     *  there is for a claim the sheet does not have (yet). */
383	    public long added(String sheetId, long claimId) {
384	        List<Long> found = jdbc.queryForList("SELECT added_seq FROM claim WHERE sheet_id = ? AND id = ?", Long.class,
385	                sheetId, claimId);
386	        return found.isEmpty() || found.get(0) == null ? Long.MAX_VALUE : found.get(0);
387	    }
388	
389	    /** Each claim's added number on the sheet, by claim id. */
390	    public Map<String, Long> added(String sheetId) {
391	        Map<String, Long> added = new LinkedHashMap<>();
392	        jdbc.query("SELECT id, added_seq FROM claim WHERE sheet_id = ?",
393	                rs -> {
394	                    added.put(String.valueOf(rs.getLong("id")), rs.getLong("added_seq"));
395	                }, sheetId);
396	        return added;
397	    }
398	
399	    /** Whether a rate for the grade the person has on a date is in force on that date (not past its
400	     *  to-date). */
401	    public boolean rated(String sheetId, long personId, LocalDate on) {
