413	     *  the rates that apply to it (see {@link #CLAIM_RATE_FOR}; {@code added} is its added number, null for all). */
414	    public BigDecimal rateInForce(String sheetId, long personId, LocalDate on, Long added) {
415	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId,
416	                personId, on.toString());
417	        if (grade.isEmpty() || grade.get(0) == null) return null;
418	        List<String> chain = new ArrayList<>();
419	        chain.add(sheetId);
420	        chain.addAll(settings.rateAncestors(sheetId));
421	        for (String at : chain) {
422	            List<BigDecimal> pct = added == null
423	                    ? jdbc.queryForList("SELECT a.pct FROM " + RATE_FOR + " a"
424	                            + " WHERE a.to_date IS NULL OR a.to_date >= CAST(? AS DATE)", BigDecimal.class,
425	                            at, grade.get(0), on.toString(), on.toString())
426	                    : jdbc.queryForList("SELECT a.pct FROM " + CLAIM_RATE_FOR + " a"
427	                            + " WHERE a.to_date IS NULL OR a.to_date >= CAST(? AS DATE)", BigDecimal.class,
428	                            at, grade.get(0), on.toString(), added, on.toString());
429	            if (!pct.isEmpty()) return pct.get(0);
430	        }
431	        return null;
432	    }
