467	    /** Move every claim of a person to another sheet, as the claims of the person {@code toPersonId} there: each keeps
468	     *  its status, dates, note, tags, settled due, status log, comments, lines and any figure a statement bound it to, and is listed
469	     *  in the same order; it loses its external reference, its lock and its settle batch. Each claim that had
470	     *  a number takes the other sheet's next one (as opening it there would give it), in the order the claims were
471	     *  opened (by the sheet's today when each was opened, then by the order they were added); a number one of them
472	     *  corrects or was split from follows it. The claims leave this sheet. */
473	    public void transferAll(String fromSheet, long personId, String toSheet, long toPersonId) {
474	        List<Long> ids = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
475	                Long.class, fromSheet, personId);
476	        Map<Long, Long> moved = new LinkedHashMap<>();
477	        for (Long claimId : ids) {
478	            GeneratedKeyHolder keys = new GeneratedKeyHolder();
479	            jdbc.update(c -> {
480	                PreparedStatement ps = c.prepareStatement("INSERT INTO claim (sheet_id, person_id, amount, claim_date, note,"
481	                        + " status, settled_due, opened_by, corrects, due_by, deferred_until, proofs, split_from, late_entry,"
482	                        + " reminded, tags, void_reason, edited_by, stated, stated_due, stated_na, waived, proofs_photo, held) SELECT ?, ?, amount, claim_date, note,"
483	                        + " status, settled_due, opened_by, corrects, due_by, deferred_until, proofs, split_from, late_entry,"
484	                        + " reminded, tags, void_reason, edited_by, stated, stated_due, stated_na, waived, proofs_photo, held FROM claim WHERE id = ? AND sheet_id = ?", new String[] { "id" });
485	                ps.setString(1, toSheet);
486	                ps.setLong(2, toPersonId);
487	                ps.setLong(3, claimId);
488	                ps.setString(4, fromSheet);
489	                return ps;
490	            }, keys);
491	            long arrived = keys.getKey().longValue();
492	            moved.put(claimId, arrived);
493	            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) SELECT ?, ?, status,"
494	                    + " by_user, on_date, due FROM claim_log WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
495	                    toSheet, arrived, fromSheet, claimId);
496	            jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, text) SELECT ?, ?, by_user,"
497	                    + " on_date, text FROM claim_comment WHERE sheet_id = ? AND claim_id = ? ORDER BY id",
498	                    toSheet, arrived, fromSheet, claimId);
499	            jdbc.update("INSERT INTO claim_line (sheet_id, claim_id, label, qty, unit) SELECT ?, ?, label, qty, unit"
500	                    + " FROM claim_line WHERE sheet_id = ? AND claim_id = ? ORDER BY id", toSheet, arrived, fromSheet, claimId);
501	            used(toSheet, jdbc.queryForObject("SELECT tags FROM claim WHERE id = ?", String.class, arrived));
502	        }
503	
504	        // Renumber on the other sheet, in the order the claims were opened.
505	        List<Object[]> numbered = jdbc.query("SELECT c.id, c.claim_no, c.due_by FROM claim c WHERE c.sheet_id = ?"
506	                + " AND c.person_id = ? AND c.claim_no IS NOT NULL ORDER BY (SELECT MIN(l.on_date) FROM claim_log l"
507	                + " WHERE l.sheet_id = c.sheet_id AND l.claim_id = c.id AND l.status = 'OPEN') NULLS LAST, c.id",
508	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getString("claim_no"), rs.getDate("due_by").toLocalDate() },
509	                fromSheet, personId);
510	        boolean perPeriod = numbersPerPeriod(toSheet);
511	        Map<String, String> numbers = new LinkedHashMap<>();
512	        for (Object[] c : numbered) {
513	            long arrived = moved.get((Long) c[0]);
514	            numbers.put((String) c[1], perPeriod ? numberInPeriod(toSheet, arrived, (LocalDate) c[2]) : number(toSheet, arrived, (LocalDate) c[2]));
515	        }
516	        for (Long arrived : moved.values()) {
517	            Map<String, Object> was = jdbc.queryForMap("SELECT corrects, split_from FROM claim WHERE id = ?", arrived);
518	            String corrects = (String) was.get("corrects");
519	            String splitFrom = (String) was.get("split_from");
520	            jdbc.update("UPDATE claim SET corrects = ?, split_from = ? WHERE id = ?",
521	                    corrects == null ? null : numbers.getOrDefault(corrects, corrects),
522	                    splitFrom == null ? null : numbers.getOrDefault(splitFrom, splitFrom), arrived);
523	            history.claim(toSheet, arrived);
524	        }
525	
526	        for (Long claimId : ids) {
527	            jdbc.update("DELETE FROM claim_log WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
528	            jdbc.update("DELETE FROM claim_comment WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
529	            jdbc.update("DELETE FROM claim_line WHERE sheet_id = ? AND claim_id = ?", fromSheet, claimId);
530	            jdbc.update("DELETE FROM claim WHERE id = ? AND sheet_id = ?", claimId, fromSheet);
531	        }
532	    }
