611	    /** The due-by of a claim created now for a person with a date: the terms-th business day after the date (skipping
612	     *  Saturdays, Sundays and the sheet's holidays), for the terms in force on the day it is created (the sheet's today):
613	     *  the person's own terms in force that day, else the terms, in force that day, of the grade the person has that day,
614	     *  else the sheet's terms in force that day. */
615	    public LocalDate dueBy(String sheetId, long personId, LocalDate date) {
616	        LocalDate on = settings.today(sheetId);
617	        // the person's own terms in force that day: the latest dated ones on or before it, else those from the beginning
618	        List<Integer> mine = new java.util.ArrayList<>();
619	        jdbc.query("SELECT terms FROM person_terms WHERE sheet_id = ? AND person_id = ? AND from_date <= ?"
620	                + " ORDER BY from_date DESC LIMIT 1", rs -> {
621	                    mine.add((Integer) rs.getObject("terms", Integer.class));
622	                }, sheetId, personId, Date.valueOf(on));
623	        if (mine.isEmpty()) {
624	            mine.addAll(jdbc.queryForList("SELECT terms FROM person WHERE sheet_id = ? AND id = ?", Integer.class,
625	                    sheetId, personId));
626	        }
627	        if (!mine.isEmpty() && mine.get(0) != null) {
628	            return settings.businessDaysAfter(sheetId, date, mine.get(0));
629	        }
630	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId, personId,
631	                on.toString());
632	        return dueByOfGrade(sheetId, grade.isEmpty() ? null : grade.get(0), date);
633	    }
