635	    /** The due-by of a claim created now with a date for a person of a grade (null when none) with no terms of their
636	     *  own: the terms-th business day after the date (skipping Saturdays, Sundays and the sheet's holidays), for the
637	     *  grade's terms in force on the day it is created (the sheet's today), else the sheet's terms in force that day. */
638	    public LocalDate dueByOfGrade(String sheetId, String grade, LocalDate date) {
639	        LocalDate on = settings.today(sheetId);
640	        Integer own = grade == null ? null : settings.gradeTerms(sheetId, grade, on);
641	        return settings.businessDaysAfter(sheetId, date, own != null ? own : settings.terms(sheetId, on));
642	    }
