644	    /** Re-fix, after a holiday is added to the sheet, the due-by of each claim not SETTLED or VOID whose due-by is on
645	     *  or after it: the terms-th business day after its date over the sheet's holidays now, for the terms it was fixed
646	     *  with (the business days from its date to its due-by over the holidays before, {@code before}). A claim whose
647	     *  due-by moves is kept in the history. */
648	    public void refixDueBy(String sheetId, java.util.Set<String> before, LocalDate holiday) {
649	        java.util.Set<String> now = new java.util.HashSet<>(before);
650	        now.add(holiday.toString());
651	        List<Object[]> open = jdbc.query("SELECT id, claim_date, due_by FROM claim WHERE sheet_id = ?"
652	                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ? ORDER BY id",
653	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getDate("claim_date").toLocalDate(),
654	                        rs.getDate("due_by").toLocalDate() }, sheetId, Date.valueOf(holiday));
655	        for (Object[] c : open) {
656	            LocalDate date = (LocalDate) c[1];
657	            LocalDate old = (LocalDate) c[2];
658	            LocalDate fixed = SettingsRepository.businessDaysAfter(now, date, businessDaysBetween(before, date, old));
659	            if (fixed.equals(old)) continue;
660	            jdbc.update("UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(fixed), c[0], sheetId);
661	            history.claim(sheetId, (Long) c[0]);
662	        }
663	    }
664	
665	    /** The business days (not a Saturday, Sunday or one of the holidays) after a date up to and including another. */
666	    private static int businessDaysBetween(java.util.Set<String> holidays, LocalDate from, LocalDate to) {
667	        int days = 0;
668	        for (LocalDate d = from.plusDays(1); !d.isAfter(to); d = d.plusDays(1)) {
669	            java.time.DayOfWeek day = d.getDayOfWeek();
670	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY && !holidays.contains(d.toString())) {
671	                days++;
672	            }
673	        }
674	        return days;
675	    }
