719	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from its last
720	     *  statement (live again); a new OPEN claim of the same person with the split-off amount, the same date and
721	     *  note and tags, opened by {@code by}, with its due-by fixed now and the original's number as split-from, is added
722	     *  (unnumbered: the caller numbers it; a late entry when its due-by falls in a soft-closed period). The new claim's id, or null when the sheet has no such OPEN claim. */
723	    public Long split(String sheetId, Claim claim, BigDecimal amount, String by) {
724	        BigDecimal rest = new BigDecimal(claim.amount()).subtract(amount);
725	        if (jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE"
726	                + " WHERE id = ? AND sheet_id = ? AND status = 'OPEN'", rest, claim.id(), sheetId) == 0) {
727	            return null;
728	        }
729	        kept(sheetId, claim.id(), true);
730	        LocalDate date = LocalDate.parse(claim.date());
731	        LocalDate dueBy = dueBy(sheetId, claim.personId(), date);
732	        boolean late = lateEntry(sheetId, dueBy);
733	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
734	        jdbc.update(c -> {
735	            PreparedStatement ps = c.prepareStatement(
736	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, due_by, status, opened_by, split_from, late_entry, tags)"
737	                            + " VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, ?, ?)",
738	                    new String[] { "id" });
739	            ps.setString(1, sheetId);
740	            ps.setLong(2, claim.personId());
741	            ps.setBigDecimal(3, amount);
742	            ps.setDate(4, Date.valueOf(date));
743	            ps.setString(5, claim.note());
744	            ps.setDate(6, Date.valueOf(dueBy));
745	            ps.setString(7, by);
746	            ps.setString(8, claim.number());
747	            ps.setBoolean(9, late);
748	            ps.setString(10, claim.tags());
749	            return ps;
750	        }, keys);
751	        kept(sheetId, keys.getKey().longValue(), true);
752	        return keys.getKey().longValue();
753	    }
