17	/** A claim's status change (open — to REVIEW instead when its due is above the review threshold in force on its date —,
18	 *  review (a steward makes a REVIEW claim OPEN), settle, approve, reject or void — a SETTLED claim too, by a steward within 7 days of its settlement), shared by the single and the bulk actions. Every
19	 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
20	public final class ClaimStatusChange {
21	    private ClaimStatusChange() {
22	    }
23	
24	    /** Open a DRAFT claim exactly as its open button does (for a paste, which opens what it adds). */
25	    public static Claim open(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
26	            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
27	        return apply(id, cid, "open", by, repository, periods, settings, audit, rollup, watches);
28	    }
