30	    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
31	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
32	        return apply(id, cid, action, null, by, repository, periods, settings, audit, rollup, watches);
33	    }
