35	    static Claim apply(String id, long cid, String action, String reason, String by, ClaimRepository repository,
36	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
37	        return apply(id, cid, action, reason, by, false, null, null, null, repository, periods, settings, audit, rollup, watches);
38	    }
