56	    /** Make every check of the status change, writing nothing: throws the refusal the change would give. */
57	    static void check(String id, long cid, String action, String by, ClaimRepository repository,
58	            PeriodRepository periods, SettingsRepository settings) throws BadRequestException {
59	        apply(id, cid, action, null, by, true, null, null, null, repository, periods, settings, null, null, null);
60	    }
