62	    /** Settle a claim split off {@code original} by a part-settle exactly as the settle button does, except that the
63	     *  four-eyes rules and the proof rule are judged on the original claim; with {@code checkOnly}, write nothing. */
64	    static Claim settlePart(String id, long cid, Claim original, String by, boolean checkOnly, ClaimRepository repository,
65	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
66	        return apply(id, cid, "settle", null, by, checkOnly, original, null, null, repository, periods, settings, audit, rollup, watches);
67	    }
