=== SavePerson.java
16:/** Save an edited person; refused (409) when someone else has saved them since the editor loaded its version.
17: *  The form's grade is recorded from its from-date (blank: the sheet's today), keeping their other grades,
18: *  except that a save leaving the grade in force on the sheet's today as it is, with the from-date blank,
19: *  records no grade. The form's terms are recorded from their from-date, keeping the others (one already recorded
20: *  for that date is replaced), or, with the from-date blank, from the beginning of time, unless they are the terms
21: *  in force on the sheet's today (then none are recorded). PERSON_EDITED carries the grade in force on the sheet's today after the save, then
22: *  the person's own terms in force on the sheet's today when the save recorded terms (empty when none are), then their contact when
23: *  the save changed it (empty when it cleared it). */
24:public class SavePerson {
25:    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
26:            @Val PersonRequest request, ServerHttpConnection connection, PersonRepository repository,
27:            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException, ConflictException {
28:        String by = CurrentUser.require(connection);
29:        String id = sheetId == null ? "" : sheetId.trim();
30:        long pid;
31:        try {
32:            pid = Long.parseLong(personId == null ? "" : personId.trim());
33:        } catch (NumberFormatException e) {
34:            throw new BadRequestException("no such person");
35:        }
36:        if (request.version() == null) {
37:            throw new BadRequestException("version is required");
38:        }
39:        if (!repository.exists(id, pid)) {
40:            throw new BadRequestException("no such person");
41:        }
42:        if (repository.nameTaken(id, request.name(), pid)) {
43:            throw new BadRequestException("name is already in use");
44:        }
45:        if (repository.aliasClashes(id, pid)) {
46:            throw new BadRequestException("an alias is already in use on another sheet of the tree");
47:        }
48:        Person current = repository.find(id, pid);
49:        // a stale editor is told so (and shown the current values) before its contact is judged against them
50:        if (current.version() != request.version()) {
51:            throw new ConflictException("someone else has saved this person; showing their current values");
52:        }
53:        String contact = request.contact().isEmpty() ? null : request.contact();
54:        if (contact != null && repository.contactTaken(id, contact, pid)) {
55:            throw new BadRequestException("contact is already in use");
56:        }
57:        boolean regrade = !request.gradeFrom().isEmpty() || !request.grade().equals(current.grade());
58:        LocalDate from = request.gradeFrom().isEmpty() ? sheets.today(id) : LocalDate.parse(request.gradeFrom());
59:        Integer terms = request.terms().isEmpty() ? null : Integer.valueOf(request.terms());
60:        boolean datedTerms = !request.termsFrom().isEmpty();
61:        boolean reterm = datedTerms || !java.util.Objects.equals(terms, current.terms());
62:        Integer baseTerms = datedTerms || !reterm ? repository.baseTerms(id, pid) : terms;
63:        boolean recontact = !java.util.Objects.equals(contact, current.contact());
64:        long version = request.version();
65:        Rollup.Snapshot before = rollup.take(id);
66:        boolean updated;
67:        try {
68:            updated = repository.update(id, pid, version, request.name(), baseTerms, contact);
69:        } catch (DuplicateKeyException e) {
70:            throw new BadRequestException("name is already in use");
71:        }
72:        if (!updated) {
73:            throw new ConflictException("someone else has saved this person; showing their current values");
74:        }
75:        repository.tags(id, pid, request.tags());
76:        if (datedTerms) {
77:            repository.terms(id, pid, terms, LocalDate.parse(request.termsFrom()));
78:        }
79:        if (regrade) {
80:            repository.grade(id, pid, request.grade(), from);
81:        }
82:        Person saved = repository.find(id, pid);
83:        audit.record("PERSON_EDITED sheet=" + id + " by=" + by + " name=" + saved.name()
84:                + " grade=" + saved.grade() + (reterm ? " terms=" + (saved.terms() == null ? "" : saved.terms()) : "")
85:                + (recontact ? " contact=" + (contact == null ? "" : contact) : ""));
86:        rollup.record(id, by, before);
87:        person.set(saved);
88:    }
89:}
