=== TransferPerson.java
18:/** A steward transfers a person to another sheet by id: they arrive there with every grade they were given (and
19: *  its from-date), their terms, contact and aliases, and their claims (see {@link ClaimRepository#transferAll}), with
20: *  their statements (see {@link PersonRepository#joinStatements}); they leave this sheet entirely (patron links, pool memberships, holds and watches dropped).
21: *  A sheet id never used is made empty first, as loading it would. Refused for anyone but a steward, for a retired
22: *  person, for this sheet's own id, and for an archived sheet. When their name or an alias is already a name or alias
23: *  of someone on the other sheet, they are merged into that person there, as {@link MergePerson} does (claims after
24: *  theirs, aliases joined, bound figures kept, statements joined; refused when that person is retired or more than one person matches);
25: *  otherwise refused when their name, an alias or their contact is already taken there. Each sheet writes its
26: *  PERSON_TRANSFERRED line (the other sheet then PERSON_MERGED when merged), then its rollup lines. */
27:public class TransferPerson {
28:    public void transfer(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
29:            @RequestBody TransferRequest request, ServerHttpConnection connection, PersonRepository people,
30:            AliasRepository aliases, ClaimRepository claims, SettingsRepository settings, SheetRepository sheets, Audit audit,
31:            Rollup rollup,
32:            Out<Person> person) throws BadRequestException {
33:        String by = CurrentUser.require(connection);
34:        String id = sheetId == null ? "" : sheetId.trim();
35:        long pid;
36:        try {
37:            pid = Long.parseLong(personId == null ? "" : personId.trim());
38:        } catch (NumberFormatException e) {
39:            throw new BadRequestException("no such person");
40:        }
41:        Person from = people.find(id, pid);
42:        if (from == null) {
43:            throw new BadRequestException("no such person");
44:        }
45:        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
46:            throw new BadRequestException("only a steward can transfer people");
47:        }
48:        String to = request == null || request.toSheetId() == null ? "" : request.toSheetId().trim();
49:        long arrived = move(id, pid, from, to, by, people, aliases, claims, settings, sheets, audit, rollup);
50:        person.set(people.find(to, arrived));
51:    }
53:    /** Transfer a person, already found on sheet {@code id}, to sheet {@code to} by the transfer rules (refused as
54:     *  {@link #transfer} refuses, beyond the steward check), writing both sheets' lines; their id on that sheet. */
55:    static long move(String id, long pid, Person from, String to, String by, PersonRepository people,
56:            AliasRepository aliases, ClaimRepository claims, SettingsRepository settings, SheetRepository sheets,
57:            Audit audit, Rollup rollup) throws BadRequestException {
58:        if (from.retired()) {
59:            throw new BadRequestException(from.name() + " is retired");
60:        }
61:        if (to.isEmpty()) {
62:            throw new BadRequestException("enter the sheet to transfer to");
63:        }
64:        if (to.equals(id)) {
65:            throw new BadRequestException("a person cannot be transferred to their own sheet");
66:        }
67:        if (settings.archived(to)) {
68:            throw new BadRequestException("sheet " + to + " is archived");
69:        }
70:        List<String> names = new ArrayList<>(List.of(from.name()));
71:        for (Alias alias : aliases.list(id)) {
72:            if (alias.personId() == pid) names.add(alias.alias());
73:        }
74:        Person into = null;
75:        for (String name : names) {
76:            Person match = people.findByName(to, name);
77:            if (match == null) continue;
78:            if (into != null && into.id() != match.id()) {
79:                throw new BadRequestException(name + " is already on sheet " + to);
80:            }
81:            into = match;
82:        }
83:        if (into != null) {
84:            if (into.retired()) {
85:                throw new BadRequestException(into.name() + " is retired");
86:            }
87:        } else {
88:            for (String name : names) {
89:                if (people.nameTaken(to, name, pid)) {
90:                    throw new BadRequestException(name + " is already on sheet " + to);
91:                }
92:            }
93:            if (from.contact() != null && people.contactTaken(to, from.contact(), 0)) {
94:                throw new BadRequestException(from.contact() + " is already on sheet " + to);
95:            }
96:        }
98:        if (!people.sheetExists(to)) {
99:            sheets.loadOrCreate(to, by);
100:        }
101:        Rollup.Snapshot beforeHere = rollup.take(id);
102:        Rollup.Snapshot beforeThere = rollup.take(to);
103:        long arrived;
104:        if (into == null) {
105:            arrived = people.transferIn(id, pid, to);
106:            claims.transferAll(id, pid, to, arrived);
107:        } else {
108:            // They arrive as merged into the person already there: their claims after that person's, their name
109:            // and aliases joined to that person's aliases.
110:            arrived = into.id();
111:            claims.transferAll(id, pid, to, arrived);
112:            people.joinAliases(to, arrived, names);
113:        }
114:        people.joinStatements(id, pid, to, arrived);
115:        people.remove(id, pid);
116:        audit.record("PERSON_TRANSFERRED sheet=" + id + " by=" + by + " name=" + from.name() + " to=" + to);
117:        rollup.record(id, by, beforeHere);
118:        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + by + " name=" + from.name() + " from=" + id);
119:        if (into != null) {
120:            audit.record("PERSON_MERGED sheet=" + to + " by=" + by + " from=" + from.name() + " into=" + into.name());
121:        }
122:        rollup.record(to, by, beforeThere);
123:        return arrived;
124:    }
125:}
