16:/** On the sheet a transfer brought a person to, a steward undoes it on the same sheet-today they arrived: the person
17: *  is transferred back to the sheet they came from by exactly the transfer rules and lines (see {@link TransferPerson}),
18: *  then this sheet writes PERSON_TRANSFER_UNDONE and its rollup lines against its figures before the undo. Refused for
19: *  anyone but a steward, on any later day, and for a person who did not arrive by transfer. */
20:public class TransferUndoPerson {
21:    public void undo(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
22:            ServerHttpConnection connection, PersonRepository people, AliasRepository aliases, ClaimRepository claims,
23:            SettingsRepository settings, SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person)
24:            throws BadRequestException {
25:        String by = CurrentUser.require(connection);
26:        String id = sheetId == null ? "" : sheetId.trim();
27:        long pid;
28:        try {
29:            pid = Long.parseLong(personId == null ? "" : personId.trim());
30:        } catch (NumberFormatException e) {
31:            throw new BadRequestException("no such person");
32:        }
33:        Person from = people.find(id, pid);
34:        if (from == null) {
35:            throw new BadRequestException("no such person");
36:        }
37:        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
38:            throw new BadRequestException("only a steward can undo a transfer");
39:        }
40:        LocalDate arrived = people.arrivedOn(id, pid);
41:        if (from.origin() == null || arrived == null) {
42:            throw new BadRequestException(from.name() + " did not arrive by transfer");
43:        }
44:        if (!arrived.equals(sheets.today(id))) {
45:            throw new BadRequestException("a transfer can only be undone on the day " + from.name() + " arrived");
46:        }
47:        String to = from.origin();
48:        Rollup.Snapshot before = rollup.take(id);
49:        long back = TransferPerson.move(id, pid, from, to, by, people, aliases, claims, settings, sheets, audit, rollup);
50:        audit.record("PERSON_TRANSFER_UNDONE sheet=" + id + " by=" + by + " name=" + from.name() + " to=" + to);
51:        rollup.record(id, by, before);
52:        person.set(people.find(to, back));
53:    }
54:}
