     1	// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
     2	// of a silent `if (res.ok)` that leaves the UI showing stale data. The rejection's message is the
     3	// server's own `error` text when it sent one.
     4	//
     5	// Every request carries the signed-in name in X-User (the server records it as `by=<user>`), and,
     6	// while this screen shows the sheet as of a date, that date in X-As-Of: reads answer as the sheet stood
     7	// then, and every change is refused.
     8	let signedInUser = '';
     9	let asOfDate = '';
    10	
    11	/** A non-2xx answer: the server's message, and its status (409 when someone else saved first). */
    12	export class HttpError extends Error {
    13	  constructor(message: string, readonly status: number) {
    14	    super(message);
    15	  }
    16	}
    17	
    18	/** Called by the session (features/session) whenever the signed-in name changes. */
    19	export function setSignedInUser(name: string): void {
    20	  signedInUser = name;
    21	}
    22	
    23	/** Called by the as-of control (features/asof) whenever the screen's as-of date changes ('' when none). */
    24	export function setAsOfDate(date: string): void {
    25	  asOfDate = date;
    26	}
    27	
    28	/** The as-of date requests are sent with ('' when none). */
    29	export function currentAsOfDate(): string {
    30	  return asOfDate;
    31	}
    32	
    33	async function send<T>(path: string, init?: RequestInit, asOf = asOfDate): Promise<T> {
    34	  const headers = new Headers(init?.headers);
    35	  if (signedInUser) headers.set('X-User', signedInUser);
    36	  if (asOf) headers.set('X-As-Of', asOf);
    37	  const res = await fetch(path, { ...init, headers });
    38	  if (!res.ok) {
    39	    let message = `${init?.method ?? 'GET'} ${path} -> ${res.status}`;
    40	    try {
    41	      const body = (await res.json()) as { error?: string };
    42	      if (body?.error) message = body.error;
    43	    } catch {
    44	      /* no JSON body: keep the status message */
    45	    }
    46	    throw new HttpError(message, res.status);
    47	  }
    48	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
    49	}
    50	
    51	export function getJson<T>(path: string): Promise<T> {
    52	  return send<T>(path);
    53	}
    54	
    55	/** A read that answers as the store holds the sheet now, whatever date this screen shows it as of. */
    56	export function getJsonNow<T>(path: string): Promise<T> {
    57	  return send<T>(path, undefined, '');
    58	}
    59	
    60	export function postJson<T>(path: string, body: unknown): Promise<T> {
    61	  return send<T>(path, {
    62	    method: 'POST',
    63	    headers: { 'Content-Type': 'application/json' },
    64	    body: JSON.stringify(body),
    65	  });
