356	    /** A sheet's ancestors, nearest first: its parent, the parent's parent and so on, stopping at a sheet seen
357	     *  before. */
358	    public List<String> lineage(String sheetId) {
359	        List<String> found = new java.util.ArrayList<>();
360	        for (String at = parent(sheetId); at != null && !found.contains(at) && !at.equals(sheetId); at = parent(at)) {
361	            found.add(at);
362	        }
363	        return found;
