366	    /** A sheet's descendants: the sheets naming it as their parent, their children and so on, nearer first,
367	     *  each once and never the sheet itself. */
368	    public List<String> descendants(String sheetId) {
369	        List<String> found = new java.util.ArrayList<>();
370	        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(sheetId));
371	        while (!pending.isEmpty()) {
372	            for (String child : jdbc.queryForList("SELECT id FROM sheet WHERE parent_id = ? ORDER BY id", String.class, pending.poll())) {
373	                if (child.equals(sheetId) || found.contains(child)) continue;
374	                found.add(child);
375	                pending.add(child);
376	            }
377	        }
378	        return found;
379	    }
