381	    /** The sheets whose rates a sheet's grade falls back to, nearest first: its ancestors up to three levels up,
382	     *  then (when it was cloned) the sheet it was cloned from and that one's own fallbacks (its ancestors, then its
383	     *  source, and so on); each once and never the sheet itself. */
384	    public List<String> rateAncestors(String sheetId) {
385	        List<String> found = new java.util.ArrayList<>();
386	        java.util.Set<String> sources = new java.util.HashSet<>();
387	        for (String at = sheetId; at != null && sources.add(at); at = clonedFrom(at)) {
388	            if (!at.equals(sheetId) && !found.contains(at)) found.add(at);
389	            List<String> up = lineage(at);
390	            for (String a : up.size() > 3 ? up.subList(0, 3) : up) {
391	                if (!a.equals(sheetId) && !found.contains(a)) found.add(a);
392	            }
393	        }
394	        return found;
395	    }
