525	    /** The terms-th business day after a date, skipping every Saturday, Sunday and one of the holidays (yyyy-MM-dd). */
526	    public static LocalDate businessDaysAfter(java.util.Set<String> holidays, LocalDate date, int terms) {
527	        int counted = 0;
528	        while (counted < terms) {
529	            date = date.plusDays(1);
530	            java.time.DayOfWeek day = date.getDayOfWeek();
531	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY
532	                    && !holidays.contains(date.toString())) {
533	                counted++;
534	            }
535	        }
536	        return date;
537	    }
