539	    /** The delegations made on the sheet, oldest first. */
540	    public List<Delegation> delegations(String sheetId) {
541	        return jdbc.query("SELECT user_name, by_user, from_date, to_date FROM delegation WHERE sheet_id = ? ORDER BY id",
542	                (rs, i) -> new Delegation(rs.getString("user_name"), rs.getString("by_user"),
543	                        rs.getDate("from_date").toLocalDate().toString(), rs.getDate("to_date").toLocalDate().toString()),
544	                sheetId);
545	    }
