547	    /** The permission matrix entries set on the sheet, by action, each a comma separated list of roles; an
548	     *  action not listed keeps the standing rule. */
549	    public Map<String, String> permissions(String sheetId) {
550	        Map<String, String> perms = new LinkedHashMap<>();
551	        jdbc.query("SELECT action, roles FROM sheet_permission WHERE sheet_id = ?",
552	                (org.springframework.jdbc.core.RowCallbackHandler) rs -> perms.put(rs.getString("action"), rs.getString("roles")),
553	                sheetId);
554	        Map<String, String> ordered = new LinkedHashMap<>();
555	        for (String action : PERMISSION_ACTIONS) {
556	            if (perms.containsKey(action)) ordered.put(action, perms.get(action));
557	        }
558	        return ordered;
559	    }
560	
561	    /** Set the roles that may take an action (a comma separated list); null or blank restores the standing rule. */
562	    public void setPermission(String sheetId, String action, String roles) {
563	        if (roles == null || roles.isEmpty()) {
564	            jdbc.update("DELETE FROM sheet_permission WHERE sheet_id = ? AND action = ?", sheetId, action);
565	        } else {
566	            jdbc.update("MERGE INTO sheet_permission (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
567	                    sheetId, action, roles);
568	        }
569	    }
570	
571	    /** Whether a user may take an action on the sheet: by the sheet's permission matrix entry for it, else the
572	     *  standing rule (open, settle, void and close by clerk and steward; reassign and reopen by steward). */
573	    public boolean allows(String sheetId, String action, String user) {
574	        List<String> found = jdbc.query("SELECT roles FROM sheet_permission WHERE sheet_id = ? AND action = ?",
575	                (rs, i) -> rs.getString("roles"), sheetId, action);
576	        List<String> roles = found.isEmpty()
577	                ? (action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : List.of(CLERK, STEWARD))
578	                : List.of(found.get(0).split(","));
579	        return roles.contains(role(sheetId, user));
580	    }
