805	/** Open the selected claims together: the server opens, in list order, each that can be opened and
806	 *  leaves the rest; the bar shows how many were opened and how many refused (gone while it runs). */
807	function BulkOpen({ sheetId }: { sheetId: string }) {
808	  const selection = useClaimSelection(sheetId);
809	  const queryClient = useQueryClient();
810	  const submitOnce = useSingleFlight();
811	  const bulk = useMutation({
812	    mutationFn: (claimIds: number[]) =>
813	      postJson<{ opened: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-open`, { claimIds }),
814	    onSuccess: () => selection.clear(),
815	    onSettled: async () => {
816	      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
817	    },
818	  });
819	  return (
820	    <p data-testid="bulk-open-bar">
821	      <button
822	        type="button"
823	        data-testid="bulk-open"
824	        disabled={bulk.isPending}
825	        onClick={() =>
826	          submitOnce(() => {
827	            bulk.reset();
828	            return bulk.mutateAsync([...selection.ids]);
829	          })
830	        }
831	      >
832	        Open selected ({selection.ids.size})
833	      </button>
834	      {bulk.isSuccess && (
835	        <>
836	          {' '}
837	          Opened <strong data-testid="bulk-opened">{bulk.data.opened}</strong>, refused{' '}
838	          <strong data-testid="bulk-refused">{bulk.data.refused}</strong>
839	        </>
840	      )}
841	      {bulk.isError && <span data-testid="bulk-open-error">{bulk.error.message}</span>}
842	    </p>
843	  );
844	}
