950	/** Re-date the selected claims together to the date typed in the bar: the server re-dates, in list order and by
951	 *  the rules of a single re-date, each that can be re-dated and leaves the rest; the bar shows how many were
952	 *  re-dated and how many refused (gone while it runs). */
953	function BulkRedate({ sheetId }: { sheetId: string }) {
954	  const selection = useClaimSelection(sheetId);
955	  const queryClient = useQueryClient();
956	  const submitOnce = useSingleFlight();
957	  const [date, setDate] = useState('');
958	  const bulk = useMutation({
959	    mutationFn: (r: { claimIds: number[]; date: string }) =>
960	      postJson<{ redated: number; refused: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-redate`, r),
961	    onSuccess: () => selection.clear(),
962	    onSettled: async () => {
