    19	
    20	/** Settle the selected claims together, all or nothing: when any of them cannot be settled by the signed-in
    21	 *  user (any refusal the single settle would give; going to PENDING is not one), none is settled, every one
    22	 *  counts as refused and nothing is written. Otherwise each is settled in list order (people in list order
    23	 *  were added, each person's claims newest first) by exactly the rules of settling one claim (a claim a clerk
    24	 *  sends to PENDING counts as settled); they are the sheet's next batch, each keeps its number, and after the
    25	 *  claims' own lines BATCH_SETTLED batch=<n> count=<claims> total=<the frozen dues of those SETTLED> is written. */
    26	public class BulkSettleClaims {
    27	    public void settle(@PathVariable("sheetId") String sheetId, @RequestBody BulkSettleRequest request,
    28	            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
    29	            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches, Out<BulkSettleResult> result) throws BadRequestException {
    30	        String by = CurrentUser.require(connection);
    31	        String id = sheetId == null ? "" : sheetId.trim();
    32	        Set<Long> selected = new LinkedHashSet<>();
    33	        if (request != null && request.claimIds() != null) {
    34	            for (Long cid : request.claimIds()) {
    35	                if (cid != null) selected.add(cid);
    36	            }
    37	        }
    38	        if (selected.isEmpty()) {
    39	            throw new BadRequestException("select at least one claim");
    40	        }
    41	        List<Claim> found = repository.inListOrder(id, selected);
    42	        boolean refusedAny = found.size() < selected.size();
    43	        for (Claim c : found) {
    44	            if (refusedAny) break;
    45	            try {
    46	                ClaimStatusChange.check(id, c.id(), "settle", by, repository, periods, settings);
    47	            } catch (BadRequestException e) {
    48	                refusedAny = true;
    49	            }
    50	        }
    51	        if (refusedAny) {
    52	            result.set(new BulkSettleResult(0, selected.size()));
    53	            return;
    54	        }
    55	        List<Long> settled = new ArrayList<>();
    56	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    57	        for (Claim c : found) {
    58	            Claim changed = ClaimStatusChange.apply(id, c.id(), "settle", by, repository, periods, settings, audit, rollup, watches);
    59	            settled.add(c.id());
    60	            if ("SETTLED".equals(changed.status()) && changed.due() != null) {
    61	                total = total.add(new BigDecimal(changed.due()));
    62	            }
    63	        }
    64	        int batch = repository.batch(id, settled);
    65	        audit.record("BATCH_SETTLED sheet=" + id + " by=" + by + " batch=" + batch + " count=" + settled.size()
    66	                + " total=" + total.toPlainString());
    67	        result.set(new BulkSettleResult(settled.size(), 0));
    68	    }
    69	}
