    55	    /** The sheet's figures now. A person's claimed is the sum of their counting claims' amounts, leaving out corrections
    56	     *  (claims that correct another). A person's due-total is the sum of their counting claims' dues now (late charges included),
    57	     *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
    58	     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). A due-total is at most the sheet's cap (an 'n/a' is not capped). The sheet's due-total skips 'n/a'.
    59	     *  The sheet's due-total and overdue-total leave out the single highest and lowest person's figure when three or more
    60	     *  people have one. */
    61	    public Snapshot take(String sheetId) {
    62	        List<Person> everyone = people.list(sheetId);
    63	        Map<Long, Figures> figures = new LinkedHashMap<>();
    64	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
    65	        List<BigDecimal> dues = new ArrayList<>();
    66	        List<BigDecimal> overdues = new ArrayList<>();
    67	        if (!everyone.isEmpty()) {
    68	            LocalDate today = sheets.today(sheetId);
    69	            List<Claim> all = claims.list(sheetId);
    70	            BigDecimal cap = settings.cap(sheetId);
    71	            for (Person p : everyone) {
    72	                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
    73	                BigDecimal due = BigDecimal.ZERO.setScale(2);
    74	                BigDecimal overdue = BigDecimal.ZERO.setScale(2);
    75	                boolean fixed = false;
    76	                for (Claim c : all) {
    77	                    if (c.personId() != p.id()) continue;
    78	                    String on = today == null ? null : today.toString();
    79	                    if (c.corrects() == null && c.countsClaimed(p.claimedHolds(on))) claimed = claimed.add(new BigDecimal(c.amount()));
    80	                    if (!c.counts(p.liveHolds(on))) continue;
    81	                    fixed |= c.fixed();
    82	                    BigDecimal now = claims.dueNow(sheetId, c);
    83	                    if (now != null) due = due.add(now);
    84	                    if (now != null && claims.overdue(sheetId, c, today)) overdue = overdue.add(now);
    85	                    fixed |= now != null;
    86	                }
    87	                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
