    90	                        shown ? due.toPlainString() : "n/a", overdue.toPlainString()));
    91	                claimedTotal = claimedTotal.add(claimed);
    92	                if (shown) dues.add(due);
    93	                overdues.add(overdue);
    94	            }
    95	        }
    96	        return new Snapshot(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
    97	                trimmed(overdues).toPlainString());
    98	    }
