   100	    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
   101	    static BigDecimal trimmed(List<BigDecimal> figures) {
   102	        List<BigDecimal> sorted = new ArrayList<>(figures);
   103	        Collections.sort(sorted);
   104	        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
   105	        BigDecimal total = BigDecimal.ZERO.setScale(2);
   106	        for (BigDecimal f : sorted) total = total.add(f);
   107	        return total;
   108	    }
   109	
   110	    /** Record one SNAPSHOT line per person (in list order) with their due-total as {@code before} had it,
   111	     *  ending with for=<steward> when {@code by} made the change under that steward's delegation (null when not),
   112	     *  and keep it on the person with the day being left. */
   113	    public void snapshot(String sheetId, String by, Snapshot before, String delegator, LocalDate dayLeft) {
   114	        for (Map.Entry<Long, Figures> e : before.people().entrySet()) {
   115	            Figures f = e.getValue();
   116	            people.snapshot(sheetId, e.getKey(), dayLeft, f.dueTotal());
   117	            audit.record("SNAPSHOT sheet=" + sheetId + " by=" + by + " name=" + f.name() + " due-total=" + f.dueTotal()
   118	                    + (delegator == null ? "" : " for=" + delegator));
   119	        }
   120	    }
   121	
   122	    /** Record the lines for every person (in list order) and the sheet's totals, moved or not. */
   123	    public void recordAll(String sheetId, String by) {
   124	        Map<Long, Figures> none = Map.of();
   125	        record(sheetId, by, new Snapshot(none, "", "", ""));
   126	    }
   127	
   128	    /** Record the lines for whatever figures moved since {@code before}. */
   129	    public void record(String sheetId, String by, Snapshot before) {
   130	        Snapshot after = take(sheetId);
   131	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
   132	            Figures now = e.getValue();
   133	            if (now.same(before.people().get(e.getKey()))) continue;
   134	            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
   135	                    + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
   136	        }
   137	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
   138	                || !after.overdueTotal().equals(before.overdueTotal())) {
   139	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
   140	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
   141	        }
   142	        BigDecimal threshold = settings.alertThreshold(sheetId);
   143	        if (threshold == null) return;
   144	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
   145	            Figures now = e.getValue();
   146	            Figures was = before.people().get(e.getKey());
   147	            if (above(now, threshold) && !above(was, threshold)) {
   148	                audit.record("ALERT sheet=" + sheetId + " by=" + by + " name=" + now.name() + " due-total=" + now.dueTotal());
   149	            }
   150	        }
   151	    }
   152	
   153	    /** Whether a person's due-total is above the threshold (no figures, or an 'n/a', is not). */
   154	    private static boolean above(Figures f, BigDecimal threshold) {
   155	        return f != null && !"n/a".equals(f.dueTotal()) && new BigDecimal(f.dueTotal()).compareTo(threshold) > 0;
   156	    }
