    47	        try {
    48	            pid = Long.parseLong(personId == null ? "" : personId.trim());
    49	        } catch (NumberFormatException e) {
    50	            throw new BadRequestException("no such person");
    51	        }
    52	        Person found = people.find(id, pid);
    53	        if (found == null) {
    54	            throw new BadRequestException("no such person");
    55	        }
    56	        LocalDate today = sheets.today(id);
    57	        LocalDate asof = input.asof();
