    24	            if (parts.length < 3 || !parts[2].startsWith("by=")) {
    25	                continue;
    26	            }
    27	            String user = parts[2].substring("by=".length());
    28	            counts.computeIfAbsent(user, u -> new TreeMap<>()).merge(parts[0], 1, Integer::sum);
    29	        }
    30	        List<String> lines = new ArrayList<>();
    31	        counts.forEach((user, events) -> events.forEach((event, n) -> lines.add(user + " " + event + " " + n)));
    32	        activity.set(new Activity(lines));
    33	    }
