    26	    @Override
    27	    public void migrate(Context context) throws Exception {
    28	        Connection c = context.getConnection();
    29	        Map<String, Set<String>> holidays = new HashMap<>();
    30	        try (PreparedStatement ps = c.prepareStatement("SELECT sheet_id, holiday_date FROM holiday");
    31	                ResultSet rs = ps.executeQuery()) {
    32	            while (rs.next()) {
    33	                holidays.computeIfAbsent(rs.getString(1), k -> new HashSet<>()).add(rs.getDate(2).toLocalDate().toString());
    34	            }
    35	        }
    36	        Map<Long, Integer> termsOf = new HashMap<>();
    37	        try (PreparedStatement claims = c.prepareStatement("SELECT id, sheet_id, person_id, claim_date, due_by FROM claim");
    38	                ResultSet rs = claims.executeQuery();
    39	                PreparedStatement update = c.prepareStatement("UPDATE claim SET due_by = ? WHERE id = ?")) {
    40	            while (rs.next()) {
    41	                long id = rs.getLong("id");
    42	                String sheetId = rs.getString("sheet_id");
    43	                LocalDate date = rs.getDate("claim_date").toLocalDate();
    44	                LocalDate old = rs.getDate("due_by").toLocalDate();
    45	                Set<String> sheetHolidays = holidays.getOrDefault(sheetId, Set.of());
    46	                Integer inForce = termsInForce(c, sheetId, rs.getLong("person_id"), date);
    47	                int terms = inForce != null && inForce >= 0 && pastHolidays(sheetHolidays, date.plusDays(inForce)).equals(old)
    48	                        ? inForce : (int) Math.max(0, ChronoUnit.DAYS.between(date, old));
    49	                termsOf.put(id, terms);
    50	                update.setDate(1, Date.valueOf(SettingsRepository.businessDaysAfter(sheetHolidays, date, terms)));
    51	                update.setLong(2, id);
    52	                update.executeUpdate();
    53	            }
    54	        }
    55	        try (PreparedStatement history = c.prepareStatement("SELECT id, sheet_id, claim_id, claim_date, due_by FROM claim_history");
    56	                ResultSet rs = history.executeQuery();
    57	                PreparedStatement update = c.prepareStatement("UPDATE claim_history SET due_by = ? WHERE id = ?")) {
    58	            while (rs.next()) {
    59	                LocalDate date = rs.getDate("claim_date").toLocalDate();
    60	                Integer terms = termsOf.get(rs.getLong("claim_id"));
    61	                if (terms == null) terms = (int) Math.max(0, ChronoUnit.DAYS.between(date, rs.getDate("due_by").toLocalDate()));
    62	                update.setDate(1, Date.valueOf(SettingsRepository.businessDaysAfter(
    63	                        holidays.getOrDefault(rs.getString("sheet_id"), Set.of()), date, terms)));
    64	                update.setLong(2, rs.getLong("id"));
    65	                update.executeUpdate();
    66	            }
    67	        }
    68	    }
