203	    /** Give an opened claim the next number in the sequence of the period its due-by ({@code date}) falls in,
204	     *  <period name>-<n>, or X-<n> when it is in no period. The sheet's row is locked first, so two
205	     *  claims opened at once get consecutive numbers. */
206	    public String numberInPeriod(String sheetId, long claimId, LocalDate date) {
207	        jdbc.update("UPDATE sheet SET claim_number = claim_number WHERE id = ?", sheetId);
208	        List<Object[]> period = periodOn(sheetId, date);
209	        String key = period.isEmpty() ? "X" : "P" + period.get(0)[0];
210	        String prefix = period.isEmpty() ? "X" : (String) period.get(0)[1];
211	        if (jdbc.update("UPDATE claim_sequence SET last_no = last_no + 1 WHERE sheet_id = ? AND seq_key = ?",
212	                sheetId, key) == 0) {
213	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_no) VALUES (?, ?, 1)", sheetId, key);
214	        }
215	        Long next = jdbc.queryForObject("SELECT last_no FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?",
216	                Long.class, sheetId, key);
217	        String number = prefix + "-" + next;
218	        jdbc.update("UPDATE claim SET claim_no = ? WHERE id = ? AND sheet_id = ?", number, claimId, sheetId);
219	        kept(sheetId, claimId, true);
