269	     *  half-even) when there is one; else half up when the claim is dated before the sheet's policy date
270	     *  (blank meaning the sheet's today), else half to even. A correction rounds by the date of the
271	     *  claim it corrects (its person's claim with that number), not its own. */
272	    public RoundingMode rounding(String sheetId, Claim claim) {
273	        String date = claim.date();
274	        if (claim.corrects() != null) {
275	            List<Date> corrected = jdbc.queryForList("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ?"
276	                    + " AND claim_no = ? ORDER BY id LIMIT 1", Date.class, sheetId, claim.personId(), claim.corrects());
277	            if (!corrected.isEmpty()) date = corrected.get(0).toLocalDate().toString();
278	        }
279	        List<String> mode = jdbc.queryForList("SELECT setting FROM setting_value WHERE sheet_id = ? AND setting_key = 'rounding'"
280	                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1", String.class, sheetId, Date.valueOf(LocalDate.parse(date)));
281	        RoundingMode set = mode.isEmpty() ? null : SettingsRepository.roundingMode(mode.get(0));
282	        if (set != null) return set;
283	        List<Date> policy = jdbc.queryForList("SELECT COALESCE(policy_date, today) FROM sheet WHERE id = ?",
284	                Date.class, sheetId);
285	        if (policy.isEmpty()) return RoundingMode.HALF_EVEN;
