    12	/** The first day (yyyy-mm-dd) of the 90 days up to and including a day. */
    13	function windowStart(today: string): string {
    14	  return new Date(Date.parse(`${today}T00:00:00Z`) - 89 * 86_400_000).toISOString().slice(0, 10);
    15	}
    16	
    17	/** Shares (in hundredths) for patrons in the order they were named: 100.00 split equally, each share rounded
    18	 *  half to even to two decimals, the remainder (100.00 less the shares added up) given to the first-named. */
    19	function shares(count: number): bigint[] {
    20	  if (count === 0) return [];
    21	  const n = BigInt(count);
    22	  let each = 10000n / n;
    23	  const rest = 10000n % n;
    24	  if (rest * 2n > n || (rest * 2n === n && each % 2n === 1n)) each += 1n;
    25	  const all = Array.from({ length: count }, () => each);
    26	  all[0] += 10000n - each * n;
    27	  return all;
    28	}
