647:      *  due-by moves is kept in the history. */
648:     public void refixDueBy(String sheetId, java.util.Set<String> before, LocalDate holiday) {
649:         java.util.Set<String> now = new java.util.HashSet<>(before);
650:         now.add(holiday.toString());
651:         List<Object[]> open = jdbc.query("SELECT id, claim_date, due_by FROM claim WHERE sheet_id = ?"
652:                 + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ? ORDER BY id",
653:                 (rs, i) -> new Object[] { rs.getLong("id"), rs.getDate("claim_date").toLocalDate(),
654:                         rs.getDate("due_by").toLocalDate() }, sheetId, Date.valueOf(holiday));
655:         for (Object[] c : open) {
656:             LocalDate date = (LocalDate) c[1];
657:             LocalDate old = (LocalDate) c[2];
658:             LocalDate fixed = SettingsRepository.businessDaysAfter(now, date, businessDaysBetween(before, date, old));
659:             if (fixed.equals(old)) continue;
660:             jdbc.update("UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(fixed), c[0], sheetId);
