    10	/** Whether a claim or its person carries a tag. */
    11	function carries(c: Claim, people: Person[] | undefined, tag: string): boolean {
    12	  const person = people?.find((p) => p.id === c.personId);
    13	  return (c.tags ?? '').split(',').includes(tag) || (person?.tags ?? '').split(',').includes(tag);
    14	}
