    16	/** Per tag ever used on the sheet, its due-total: the dues of the claims that count (as in a person's
    17	 *  due-total) which carry it, or whose person carries it, added up once each, skipping 'n/a' (a claim
    18	 *  with two tags counts in both). */
    19	function TagTotals({ sheetId }: { sheetId: string }) {
    20	  const fig = useFigure();
    21	  const tags = useTagsUsed(sheetId);
    22	  const claims = useClaims(sheetId);
    23	  const people = usePeople(sheetId);
    24	  const rates = useRates(sheetId);
    25	  const settings = useSettings(sheetId).data;
    26	  const today = useSheetToday(sheetId).data?.today;
    27	  const holds = holdsById(people.data, today);
    28	  const dues = new Map<number, string>();
    29	  for (const c of claims.data ?? []) {
    30	    const person = people.data?.find((p) => p.id === c.personId);
    31	    if ((c.tags === null && !person?.tags) || !counts(c, holds, today)) continue;
    32	    const grade = gradeOn(person, c.date);
    33	    dues.set(c.id, claimDueNow(c, claims.data, rateFor(rates.data, grade, c.date, c.added), settings, today, grade));
    34	  }
    35	  return (
    36	    <section data-testid="tag-totals">
    37	      <table>
    38	        <thead>
    39	          <tr>
    40	            <th>Tag</th>
    41	            <th>Due total</th>
    42	          </tr>
    43	        </thead>
    44	        <tbody>
    45	          {(tags.data ?? []).map((t) => (
    46	            <tr key={t}>
    47	              <td>{t}</td>
    48	              <td data-testid={`tag-${t}-due-total`}>
    49	                {fig(sumDues((claims.data ?? []).filter((c) => dues.has(c.id) && carries(c, people.data, t)).map((c) => dues.get(c.id)!)))}
    50	              </td>
    51	            </tr>
    52	          ))}
    53	        </tbody>
    54	      </table>
